// Regenerates src/apps/sheets/engine/engineBundle.gen.js — a self-contained
// IIFE bundle of the Sheets formula engine (tokenizer, parser, evaluator,
// built-in functions, number formatting). It is embedded verbatim (via a
// `?raw` import) into every "Living spreadsheet (.html)" export so the
// exported file can recalculate formulas fully offline, in any browser, with
// no dependency on the rest of Anleo Office. See src/apps/sheets/livingExport.ts.
//
// This script is intentionally NOT wired into package.json — the shell app
// owns package.json this round. Regenerate by hand after any change under
// src/apps/sheets/engine/** :
//
//   node scripts/build-engine-bundle.mjs
//
// Then commit the updated engineBundle.gen.js — it is a source artifact, not
// a build output that gets regenerated by `npm run build`.

import { build } from 'vite'
import { fileURLToPath } from 'node:url'
import { mkdtempSync, readFileSync, writeFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const root = resolve(__dirname, '..')
const entry = resolve(root, 'src/apps/sheets/engine/standalone.ts')
const finalPath = resolve(root, 'src/apps/sheets/engine/engineBundle.gen.js')

// Build into a scratch temp dir, never directly into src/ — the engine folder
// is source, and vite's lib build empties its outDir by default.
const tmpOut = mkdtempSync(join(tmpdir(), 'anleo-engine-bundle-'))
const tmpFile = 'bundle.js'

try {
  await build({
    root,
    configFile: false,
    logLevel: 'warn',
    build: {
      write: true,
      outDir: tmpOut,
      emptyOutDir: true,
      minify: false,
      target: 'es2018',
      lib: {
        entry,
        formats: ['iife'],
        // Unused (standalone.ts has no exports — it assigns globalThis.AnleoEngine
        // itself), but rollup's iife format wants a name.
        name: 'AnleoEngineBuildOutput',
        fileName: () => tmpFile,
      },
    },
  })

  const code = readFileSync(join(tmpOut, tmpFile), 'utf8')
  const header = `// GENERATED FILE — do not hand-edit.
// Source: src/apps/sheets/engine/standalone.ts (+ the rest of engine/**).
// Regenerate with: node scripts/build-engine-bundle.mjs
//
// A self-contained IIFE bundle of the Sheets formula engine, embedded into
// the "Living spreadsheet" export (see src/apps/sheets/livingExport.ts) so
// exported .html files can recalculate formulas fully offline, with no
// dependency on the rest of the app. Sets globalThis.AnleoEngine.computeSheet.
`
  writeFileSync(finalPath, header + code)
  console.log('Wrote', finalPath, `(${code.length} bytes)`)
} finally {
  rmSync(tmpOut, { recursive: true, force: true })
}
